import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.BbQrW5_t.js";const b=JSON.parse('{"title":"《AI Agent 实战》Chapter 2 核心知识点提炼","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/02-chapter2.md","filePath":"study/ai-agent-book/02-chapter2.md","lastUpdated":1785465991000}'),o={name:"study/ai-agent-book/02-chapter2.md"};function i(d,t,n,h,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="《ai-agent-实战》chapter-2-核心知识点提炼" tabindex="-1">《AI Agent 实战》Chapter 2 核心知识点提炼 <a class="header-anchor" href="#《ai-agent-实战》chapter-2-核心知识点提炼" aria-label="Permalink to &quot;《AI Agent 实战》Chapter 2 核心知识点提炼&quot;">​</a></h1><h2 id="第二章-上下文工程" tabindex="-1">第二章：上下文工程 <a class="header-anchor" href="#第二章-上下文工程" aria-label="Permalink to &quot;第二章：上下文工程&quot;">​</a></h2><hr><h2 id="一、核心概念-上下文决定能力上限" tabindex="-1">一、核心概念：上下文决定能力上限 <a class="header-anchor" href="#一、核心概念-上下文决定能力上限" aria-label="Permalink to &quot;一、核心概念：上下文决定能力上限&quot;">​</a></h2><h3 id="_1-1-什么是上下文" tabindex="-1">1.1 什么是上下文 <a class="header-anchor" href="#_1-1-什么是上下文" aria-label="Permalink to &quot;1.1 什么是上下文&quot;">​</a></h3><ul><li><strong>定义</strong>：每次与 AI 对话时，AI 实际&quot;看到&quot;的全部信息</li><li><strong>组成部分</strong>： <ul><li>对话历史</li><li>系统指令（System Prompt）</li><li>工具描述（Tool Definitions）</li><li>其他元信息</li></ul></li></ul><h3 id="_1-2-核心观点" tabindex="-1">1.2 核心观点 <a class="header-anchor" href="#_1-2-核心观点" aria-label="Permalink to &quot;1.2 核心观点&quot;">​</a></h3><blockquote><p><strong>&quot;上下文的质量才是 Agent 能力的真正上限&quot;</strong></p></blockquote><ul><li>模型本身的智力只是基础</li><li>中等能力模型 + 精心组织的上下文 &gt; 顶级模型 + 信息匮乏</li><li>决定 Agent 能力上限的不是模型参数量，而是每个决策点能获得多少、多精准的上下文</li></ul><h3 id="_1-3-上下文工程的双重属性" tabindex="-1">1.3 上下文工程的双重属性 <a class="header-anchor" href="#_1-3-上下文工程的双重属性" aria-label="Permalink to &quot;1.3 上下文工程的双重属性&quot;">​</a></h3><ul><li><strong>技术问题</strong>：如何组织和管理信息</li><li><strong>组织问题</strong>：团队的文档化程度决定 Agent 能发挥的效力</li></ul><hr><h2 id="二、api-消息结构-理解上下文的技术基础" tabindex="-1">二、API 消息结构：理解上下文的技术基础 <a class="header-anchor" href="#二、api-消息结构-理解上下文的技术基础" aria-label="Permalink to &quot;二、API 消息结构：理解上下文的技术基础&quot;">​</a></h2><h3 id="_2-1-消息的四种角色" tabindex="-1">2.1 消息的四种角色 <a class="header-anchor" href="#_2-1-消息的四种角色" aria-label="Permalink to &quot;2.1 消息的四种角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>含义</th><th>来源</th></tr></thead><tbody><tr><td><code>system</code></td><td>系统提示词</td><td>开发者编写，最高优先级</td></tr><tr><td><code>user</code></td><td>用户消息</td><td>终端用户输入</td></tr><tr><td><code>assistant</code></td><td>助手消息</td><td>模型生成（文本回复或工具调用）</td></tr><tr><td><code>tool</code></td><td>工具结果</td><td>Agent 框架执行工具后返回</td></tr></tbody></table><h3 id="_2-2-agent-核心循环-react-循环" tabindex="-1">2.2 Agent 核心循环（ReAct 循环） <a class="header-anchor" href="#_2-2-agent-核心循环-react-循环" aria-label="Permalink to &quot;2.2 Agent 核心循环（ReAct 循环）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 → 工具调用 → 执行 → 送回结果 → 再请求</span></span></code></pre></div><p><strong>关键特性</strong>：</p><ul><li>每次 API 调用都是<strong>无状态</strong>的</li><li>所有模型需要的信息必须在消息列表中完整提供</li><li>Agent 框架的核心工作：管理 messages 列表</li></ul><h3 id="_2-3-上下文的静态与动态划分" tabindex="-1">2.3 上下文的静态与动态划分 <a class="header-anchor" href="#_2-3-上下文的静态与动态划分" aria-label="Permalink to &quot;2.3 上下文的静态与动态划分&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│  静态前缀（缓存友好）            │</span></span>
<span class="line"><span>│  - System Prompt                │</span></span>
<span class="line"><span>│  - Tool Definitions             │</span></span>
<span class="line"><span>├─────────────────────────────────┤</span></span>
<span class="line"><span>│  动态轨迹（持续增长）            │</span></span>
<span class="line"><span>│  - User 消息                    │</span></span>
<span class="line"><span>│  - Assistant 回复               │</span></span>
<span class="line"><span>│  - Tool 执行结果                 │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="三、kv-cache-底层优化原理" tabindex="-1">三、KV Cache：底层优化原理 <a class="header-anchor" href="#三、kv-cache-底层优化原理" aria-label="Permalink to &quot;三、KV Cache：底层优化原理&quot;">​</a></h2><h3 id="_3-1-什么是-kv-cache" tabindex="-1">3.1 什么是 KV Cache <a class="header-anchor" href="#_3-1-什么是-kv-cache" aria-label="Permalink to &quot;3.1 什么是 KV Cache&quot;">​</a></h3><ul><li><strong>作用</strong>：缓存已处理 token 的 Key-Value 向量，避免重复计算</li><li><strong>价值</strong>：将计算量从 O(N²) 降低到 O(N)</li><li><strong>约束</strong>：前缀必须完全不变，任何改动都会导致缓存失效</li></ul><h3 id="_3-2-核心结论-必须记住" tabindex="-1">3.2 核心结论（必须记住） <a class="header-anchor" href="#_3-2-核心结论-必须记住" aria-label="Permalink to &quot;3.2 核心结论（必须记住）&quot;">​</a></h3><blockquote><p><strong>三条铁律</strong>：</p><ol><li>系统提示词和工具定义一旦确定就不要改</li><li>动态信息永远追加到末尾</li><li>使用标准 API 格式，不要自行拼接消息</li></ol></blockquote><h3 id="_3-3-常见错误模式" tabindex="-1">3.3 常见错误模式 <a class="header-anchor" href="#_3-3-常见错误模式" aria-label="Permalink to &quot;3.3 常见错误模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>错误模式</th><th>问题</th></tr></thead><tbody><tr><td>动态系统提示词（如嵌入时间戳）</td><td>缓存完全失效</td></tr><tr><td>滑动窗口对话历史</td><td>破坏前缀一致性 + 丢失工具结果</td></tr><tr><td>文本格式化（自行拼接消息）</td><td>偏离模型训练格式，削弱能力</td></tr><tr><td>工具定义动态排序</td><td>缓存失效</td></tr></tbody></table><h3 id="_3-4-kv-cache-vs-prompt-cache" tabindex="-1">3.4 KV Cache vs Prompt Cache <a class="header-anchor" href="#_3-4-kv-cache-vs-prompt-cache" aria-label="Permalink to &quot;3.4 KV Cache vs Prompt Cache&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>作用范围</th><th>经济影响</th></tr></thead><tbody><tr><td>KV Cache</td><td>单次请求内</td><td>性能优化</td></tr><tr><td>Prompt Cache</td><td>跨请求</td><td>直接影响计费</td></tr></tbody></table><hr><h2 id="四、提示工程-系统提示词设计" tabindex="-1">四、提示工程：系统提示词设计 <a class="header-anchor" href="#四、提示工程-系统提示词设计" aria-label="Permalink to &quot;四、提示工程：系统提示词设计&quot;">​</a></h2><h3 id="_4-1-设计原则" tabindex="-1">4.1 设计原则 <a class="header-anchor" href="#_4-1-设计原则" aria-label="Permalink to &quot;4.1 设计原则&quot;">​</a></h3><p><strong>检验标准</strong>：大模型是一位聪明的新员工，能力出众但对你的一无所知。如果读完系统提示词还不知道该怎么做，Agent 也一样不知道。</p><h3 id="_4-2-语气与风格" tabindex="-1">4.2 语气与风格 <a class="header-anchor" href="#_4-2-语气与风格" aria-label="Permalink to &quot;4.2 语气与风格&quot;">​</a></h3><ul><li>大写字母（如 &quot;NEVER do X&quot;）更能引起模型注意</li><li>但过度使用会导致效果稀释，保留给真正关键的约束</li></ul><h3 id="_4-3-结构化提示" tabindex="-1">4.3 结构化提示 <a class="header-anchor" href="#_4-3-结构化提示" aria-label="Permalink to &quot;4.3 结构化提示&quot;">​</a></h3><ul><li><strong>XML 标签</strong>：层次化语义，机器可解析</li><li><strong>Markdown</strong>：保持可读性，轻量级组织</li></ul><h3 id="_4-4-流程驱动-vs-规则堆砌" tabindex="-1">4.4 流程驱动 vs 规则堆砌 <a class="header-anchor" href="#_4-4-流程驱动-vs-规则堆砌" aria-label="Permalink to &quot;4.4 流程驱动 vs 规则堆砌&quot;">​</a></h3><p><strong>流程驱动的优势</strong>：</p><ul><li>模型清楚知道当前处于哪个阶段</li><li>异常处理有据可依</li><li>避免&quot;遍历所有规则寻找匹配&quot;</li></ul><h3 id="_4-5-业务规则细化" tabindex="-1">4.5 业务规则细化 <a class="header-anchor" href="#_4-5-业务规则细化" aria-label="Permalink to &quot;4.5 业务规则细化&quot;">​</a></h3><p><strong>核心观点</strong>：</p><blockquote><p>模型的优势在于遵循复杂指令和从长上下文中提取信息，但不应该在业务规则制定上被赋予过多自由裁量权。</p></blockquote><p><strong>实践建议</strong>：</p><ul><li>产品经理负责规则设计</li><li>工程师负责规则编码</li><li>规则必须明确到可执行的程度</li></ul><h3 id="_4-6-few-shot-示例" tabindex="-1">4.6 Few-shot 示例 <a class="header-anchor" href="#_4-6-few-shot-示例" aria-label="Permalink to &quot;4.6 Few-shot 示例&quot;">​</a></h3><p><strong>何时使用</strong>：</p><ul><li>输出难以用规则精确描述时</li><li>特定风格的文案、结构化格式、语气分寸</li></ul><p><strong>最佳实践</strong>：</p><ul><li>2-3 个精选示例胜过 10 个相似示例</li><li>示例位置保持字节级稳定（缓存友好）</li></ul><h3 id="_4-7-工具定义设计" tabindex="-1">4.7 工具定义设计 <a class="header-anchor" href="#_4-7-工具定义设计" aria-label="Permalink to &quot;4.7 工具定义设计&quot;">​</a></h3><p><strong>关键要素</strong>：</p><ul><li>使用边界（&quot;NEVER invoke grep as a Bash command&quot;）</li><li>具体示例</li><li>性能提示</li><li>工具间协作关系</li></ul><hr><h2 id="五、提示注入攻防" tabindex="-1">五、提示注入攻防 <a class="header-anchor" href="#五、提示注入攻防" aria-label="Permalink to &quot;五、提示注入攻防&quot;">​</a></h2><h3 id="_5-1-什么是提示注入" tabindex="-1">5.1 什么是提示注入 <a class="header-anchor" href="#_5-1-什么是提示注入" aria-label="Permalink to &quot;5.1 什么是提示注入&quot;">​</a></h3><ul><li>攻击者通过外部内容将伪装成系统指令的文本混入上下文</li><li>Agent 拥有工具调用能力，危害远超普通聊天机器人</li></ul><h3 id="_5-2-上下文层防御策略" tabindex="-1">5.2 上下文层防御策略 <a class="header-anchor" href="#_5-2-上下文层防御策略" aria-label="Permalink to &quot;5.2 上下文层防御策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>方法</th></tr></thead><tbody><tr><td>来源标记</td><td><code>&lt;external_content source=&quot;webpage&quot;&gt;...&lt;/external_content&gt;</code></td></tr><tr><td>结构化角色</td><td>严格利用 Chat Template 的角色体系</td></tr><tr><td>输入清洗</td><td>过滤可疑模式（容易被绕过，仅作辅助）</td></tr></tbody></table><h3 id="_5-3-新注入面" tabindex="-1">5.3 新注入面 <a class="header-anchor" href="#_5-3-新注入面" aria-label="Permalink to &quot;5.3 新注入面&quot;">​</a></h3><ul><li>Agent Skills：第三方 Skill 内容以高执行倾向进入上下文</li><li>Agent 状态栏：状态栏投毒风险</li></ul><hr><h2 id="六、agent-skills-动态提示词与按需加载" tabindex="-1">六、Agent Skills：动态提示词与按需加载 <a class="header-anchor" href="#六、agent-skills-动态提示词与按需加载" aria-label="Permalink to &quot;六、Agent Skills：动态提示词与按需加载&quot;">​</a></h2><h3 id="_6-1-核心思想" tabindex="-1">6.1 核心思想 <a class="header-anchor" href="#_6-1-核心思想" aria-label="Permalink to &quot;6.1 核心思想&quot;">​</a></h3><blockquote><p>不是把所有知识一次性塞给 Agent，而是让它按需加载</p></blockquote><h3 id="_6-2-渐进式披露三层结构" tabindex="-1">6.2 渐进式披露三层结构 <a class="header-anchor" href="#_6-2-渐进式披露三层结构" aria-label="Permalink to &quot;6.2 渐进式披露三层结构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>内容</th><th>Token 量</th></tr></thead><tbody><tr><td>第一层</td><td>元数据（name + description）</td><td>数百 token</td></tr><tr><td>第二层</td><td>核心流程（SKILL.md）</td><td>按需加载</td></tr><tr><td>第三层</td><td>细则（子文档）</td><td>按需深入</td></tr></tbody></table><h3 id="_6-3-三种实现方式对比" tabindex="-1">6.3 三种实现方式对比 <a class="header-anchor" href="#_6-3-三种实现方式对比" aria-label="Permalink to &quot;6.3 三种实现方式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>注入 system 消息</td><td>指令遵循效果最好</td><td>破坏 KV Cache</td></tr><tr><td>作为普通文件读取</td><td>不破坏缓存</td><td>依赖模型的中间位置指令遵循能力</td></tr><tr><td><strong>生产实现</strong></td><td>元数据提前提供 + 完整内容按需加载</td><td>兼顾缓存和效果</td></tr></tbody></table><h3 id="_6-4-skill-描述的设计要点" tabindex="-1">6.4 Skill 描述的设计要点 <a class="header-anchor" href="#_6-4-skill-描述的设计要点" aria-label="Permalink to &quot;6.4 Skill 描述的设计要点&quot;">​</a></h3><ul><li><strong>必须包含反例</strong>：&quot;Don&#39;t use when...&quot;</li><li>缺少反例会导致路由准确率明显下降</li></ul><hr><h2 id="七、agent-状态栏-元信息增强" tabindex="-1">七、Agent 状态栏：元信息增强 <a class="header-anchor" href="#七、agent-状态栏-元信息增强" aria-label="Permalink to &quot;七、Agent 状态栏：元信息增强&quot;">​</a></h2><h3 id="_7-1-核心原理" tabindex="-1">7.1 核心原理 <a class="header-anchor" href="#_7-1-核心原理" aria-label="Permalink to &quot;7.1 核心原理&quot;">​</a></h3><blockquote><p><strong>上下文学习更像检索而非推理</strong></p></blockquote><ul><li>注意力擅长在已有内容中&quot;查找&quot;</li><li>不擅长主动&quot;归纳统计&quot;</li><li>状态栏：把分散的隐式状态提炼为显式知识</li></ul><h3 id="_7-2-类比" tabindex="-1">7.2 类比 <a class="header-anchor" href="#_7-2-类比" aria-label="Permalink to &quot;7.2 类比&quot;">​</a></h3><ul><li>系统提示词 = 员工手册（入职时发，不变）</li><li>Agent 状态栏 = 实时仪表盘（随任务推进更新）</li></ul><h3 id="_7-3-实现位置" tabindex="-1">7.3 实现位置 <a class="header-anchor" href="#_7-3-实现位置" aria-label="Permalink to &quot;7.3 实现位置&quot;">​</a></h3><ul><li>作为 <strong>user 角色</strong>消息追加到上下文末尾</li><li>不修改 system 消息，保护 KV Cache</li></ul><h3 id="_7-4-状态栏包含的信息" tabindex="-1">7.4 状态栏包含的信息 <a class="header-anchor" href="#_7-4-状态栏包含的信息" aria-label="Permalink to &quot;7.4 状态栏包含的信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>示例</th></tr></thead><tbody><tr><td>任务规划</td><td>TODO 列表</td></tr><tr><td>侧信道信息</td><td>时间戳、地理位置</td></tr><tr><td>环境状态</td><td>工作目录、系统时间</td></tr><tr><td>可用能力清单</td><td>Skills 元数据</td></tr></tbody></table><h3 id="_7-5-状态更新的两种实现" tabindex="-1">7.5 状态更新的两种实现 <a class="header-anchor" href="#_7-5-状态更新的两种实现" aria-label="Permalink to &quot;7.5 状态更新的两种实现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>实现方式</th><th>缓存代价</th><th>适用场景</th></tr></thead><tbody><tr><td>每轮替换</td><td>末尾缓存失效</td><td>轨迹较短或状态消息很大</td></tr><tr><td>持久追加</td><td>完全友好</td><td>状态更新频繁且轨迹很长</td></tr></tbody></table><h3 id="_7-6-三条实践经验" tabindex="-1">7.6 三条实践经验 <a class="header-anchor" href="#_7-6-三条实践经验" aria-label="Permalink to &quot;7.6 三条实践经验&quot;">​</a></h3><ol><li><strong>状态栏用代码维护，别用 LLM</strong></li><li><strong>删原文前，确认状态栏覆盖所有可能问题</strong></li><li><strong>把状态栏准确率当成生产指标盯住</strong></li></ol><hr><h2 id="八、上下文压缩策略" tabindex="-1">八、上下文压缩策略 <a class="header-anchor" href="#八、上下文压缩策略" aria-label="Permalink to &quot;八、上下文压缩策略&quot;">​</a></h2><h3 id="_8-1-压缩的双重动机" tabindex="-1">8.1 压缩的双重动机 <a class="header-anchor" href="#_8-1-压缩的双重动机" aria-label="Permalink to &quot;8.1 压缩的双重动机&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动机</th><th>说明</th></tr></thead><tbody><tr><td>解决长度约束</td><td>窗口有限，token 成本</td></tr><tr><td>提升思考质量</td><td>总结后的知识比原始形式更易使用</td></tr></tbody></table><h3 id="_8-2-上下文腐化-context-rot" tabindex="-1">8.2 上下文腐化（Context Rot） <a class="header-anchor" href="#_8-2-上下文腐化-context-rot" aria-label="Permalink to &quot;8.2 上下文腐化（Context Rot）&quot;">​</a></h3><blockquote><p>&quot;装得下但找不到了&quot;</p></blockquote><ul><li>无关内容占据上下文大头</li><li>决策质量悄然下降</li><li>比上下文溢出更隐蔽</li></ul><h3 id="_8-3-压缩与-kv-cache-的关系" tabindex="-1">8.3 压缩与 KV Cache 的关系 <a class="header-anchor" href="#_8-3-压缩与-kv-cache-的关系" aria-label="Permalink to &quot;8.3 压缩与 KV Cache 的关系&quot;">​</a></h3><ul><li>压缩发生在<strong>两次 API 调用之间</strong></li><li>System Prompt 和 Tool Definitions 永远不动</li><li>压缩对象是对话历史中的 tool results</li></ul><h3 id="_8-4-六种压缩策略对比" tabindex="-1">8.4 六种压缩策略对比 <a class="header-anchor" href="#_8-4-六种压缩策略对比" aria-label="Permalink to &quot;8.4 六种压缩策略对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>Token 量</th><th>特点</th></tr></thead><tbody><tr><td>无压缩</td><td>—</td><td>溢出失败</td></tr><tr><td>个体摘要</td><td>276,608</td><td>信息碎片化</td></tr><tr><td>组合摘要</td><td>93,449</td><td>可能丢失末尾信息</td></tr><tr><td><strong>上下文感知压缩</strong></td><td>40,157</td><td>最佳性价比</td></tr><tr><td>带引用的上下文感知</td><td>222,992</td><td>提供溯源</td></tr><tr><td>自适应窗口化</td><td>174,601</td><td>前期保留完整信息</td></tr></tbody></table><h3 id="_8-5-生产级分层压缩机制" tabindex="-1">8.5 生产级分层压缩机制 <a class="header-anchor" href="#_8-5-生产级分层压缩机制" aria-label="Permalink to &quot;8.5 生产级分层压缩机制&quot;">​</a></h3><ol><li><strong>工具结果预算控制</strong>：大输出存磁盘，只看摘要</li><li><strong>噪声直接删除</strong>：不做摘要，直接移除</li><li><strong>API 层微压缩</strong>：服务端移除指定内容</li><li><strong>归档式摘要</strong>：保留对话逻辑脉络</li><li><strong>全量压缩</strong>：最后手段，配备熔断器</li></ol><h3 id="_8-6-压缩时必须保留的内容" tabindex="-1">8.6 压缩时必须保留的内容 <a class="header-anchor" href="#_8-6-压缩时必须保留的内容" aria-label="Permalink to &quot;8.6 压缩时必须保留的内容&quot;">​</a></h3><ul><li>架构决策和关键约束（不得摘要）</li><li>已修改的文件列表和关键变更记录</li><li>验证状态（pass/fail）</li><li>未解决的 TODO 和回滚笔记</li><li>UUID、hash、IP、端口、URL、文件名等标识符</li></ul><h3 id="_8-7-隔离优于压缩" tabindex="-1">8.7 隔离优于压缩 <a class="header-anchor" href="#_8-7-隔离优于压缩" aria-label="Permalink to &quot;8.7 隔离优于压缩&quot;">​</a></h3><blockquote><p><strong>子 Agent 上下文隔离</strong></p></blockquote><ul><li>把大体积中间信息隔离在子 Agent 上下文</li><li>主上下文只接收结论性摘要</li><li>用隔离代替压缩，从源头避免噪声</li></ul><hr><h2 id="九、核心洞察与金句" tabindex="-1">九、核心洞察与金句 <a class="header-anchor" href="#九、核心洞察与金句" aria-label="Permalink to &quot;九、核心洞察与金句&quot;">​</a></h2><h3 id="_9-1-关于上下文" tabindex="-1">9.1 关于上下文 <a class="header-anchor" href="#_9-1-关于上下文" aria-label="Permalink to &quot;9.1 关于上下文&quot;">​</a></h3><blockquote><p>&quot;人和模型一样，最重要的是 Context。&quot; —— 翁家翌（OpenAI 研究员）</p></blockquote><h3 id="_9-2-关于能力上限" tabindex="-1">9.2 关于能力上限 <a class="header-anchor" href="#_9-2-关于能力上限" aria-label="Permalink to &quot;9.2 关于能力上限&quot;">​</a></h3><blockquote><p>一个中等能力的模型配上精心组织的上下文，往往能胜过一个顶级模型在信息匮乏下的盲目摸索。</p></blockquote><h3 id="_9-3-关于文档化" tabindex="-1">9.3 关于文档化 <a class="header-anchor" href="#_9-3-关于文档化" aria-label="Permalink to &quot;9.3 关于文档化&quot;">​</a></h3><blockquote><p>AI Agent 就像一个永远的新员工：给足背景信息，它能干得很好；什么都不告诉它，再聪明也是白搭。</p></blockquote><h3 id="_9-4-关于状态栏" tabindex="-1">9.4 关于状态栏 <a class="header-anchor" href="#_9-4-关于状态栏" aria-label="Permalink to &quot;9.4 关于状态栏&quot;">​</a></h3><blockquote><p>状态栏之所以有效，根子上是因为它给模型喂进了它自己想不出来的信息。</p></blockquote><h3 id="_9-5-关于压缩" tabindex="-1">9.5 关于压缩 <a class="header-anchor" href="#_9-5-关于压缩" aria-label="Permalink to &quot;9.5 关于压缩&quot;">​</a></h3><blockquote><p>压缩即理解——不要让模型被动地在海量信息中检索，而要主动为模型提供经过提炼的结构化知识。</p></blockquote><hr><h2 id="十、思考题要点" tabindex="-1">十、思考题要点 <a class="header-anchor" href="#十、思考题要点" aria-label="Permalink to &quot;十、思考题要点&quot;">​</a></h2><ol><li><strong>滑动窗口 vs 完整历史</strong> → 策略：分层保留 + 自适应压缩</li><li><strong>思维链保留策略</strong> → DeepSeek R1 剥离 vs V4 强制回传，体现&quot;思考是状态，不是废料&quot;</li><li><strong>极端压缩风险</strong> → 不可逆信息损失，需保留关键标识符 + 溯源引用</li><li><strong>状态栏可靠性</strong> → 用代码维护 + 生产指标监控</li><li><strong>系统提示词熵增</strong> → 版本控制 + 消融实验验证</li><li><strong>检索 vs 推理局限</strong> → 需要新的架构突破（如交互缩放）</li><li><strong>Skills 元认知问题</strong> → 需要模型知道&quot;自己不知道什么&quot;</li><li><strong>模型对 Skills 支持差异</strong> → 训练数据差异导致</li><li><strong>工具集频繁变动</strong> → 按需加载机制 + 固定元数据前缀</li></ol><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本章核心：<strong>给模型看什么、怎么组织，比模型本身有多聪明更影响最终结果</strong></p><p>技术链条：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API 消息结构 → KV Cache 约束 → 提示工程 → Skills 按需加载 → 状态栏注入 → 压缩策略</span></span></code></pre></div><p>共同特点：<strong>显式的、工程化的信息管理</strong></p><ul><li>不要让模型被动寻找</li><li>主动提供经过提炼的结构化状态</li><li>用工程手段最大化信息利用效率</li></ul>`,128)])])}const p=a(o,[["render",i]]);export{b as __pageData,p as default};
